import{_ as a,y as e,S as r,M as t}from"./chunks/framework.a6902a73.js";const p=JSON.parse('{"title":"函数总览","description":"","frontmatter":{},"headers":[],"relativePath":"src/functions/index.md","filePath":"src/functions/index.md"}'),i={name:"src/functions/index.md"},l=t('<h1 id="函数总览" tabindex="-1">函数总览 <a class="header-anchor" href="#函数总览" aria-label="Permalink to &quot;函数总览&quot;">​</a></h1><p><code>gmap-ol</code>提供了一系列开箱即用的地图工具函数，按功能分为以下六类。</p><h2 id="图层操作" tabindex="-1">图层操作 <a class="header-anchor" href="#图层操作" aria-label="Permalink to &quot;图层操作&quot;">​</a></h2><ul><li><a href="/src/functions/layerOperation/getLayerByName.html">getLayerByName</a>：通过<code>layerName</code>获取地图对应的图层（精确匹配）。</li><li><a href="/src/functions/layerOperation/getLayerByNameParam.html">getLayerByNameParam</a>：通过 WMS 图层的<code>LAYERS</code>参数查找对应图层。</li><li><a href="/src/functions/layerOperation/getAllLayers.html">getAllLayers</a>：获取地图中的所有图层（含图层组内嵌套的图层）。</li><li><a href="/src/functions/layerOperation/getLayerUrl.html">getLayerUrl</a>：获取 WMS/WMTS 图层的服务地址 URL。</li><li><a href="/src/functions/layerOperation/removeLayer.html">removeLayer</a>：按<code>layerName</code>清除并移除匹配的图层。</li><li><a href="/src/functions/layerOperation/setLayerVisible.html">setLayerVisible</a>：按<code>layerName</code>设置匹配图层的显示/隐藏。</li><li><a href="/src/functions/layerOperation/getOptionsStyle.html">getOptionsStyle</a>：根据配置项获取要素样式。</li><li><a href="/src/functions/layerOperation/judgeLayerVisible.html">judgeLayerVisible</a>：判断指定图层当前是否可见。</li></ul><h2 id="数据加载" tabindex="-1">数据加载 <a class="header-anchor" href="#数据加载" aria-label="Permalink to &quot;数据加载&quot;">​</a></h2><ul><li><a href="/src/functions/dataLoad/point.html">Point</a>：添加点图层（<code>addPointLayer</code>/<code>addPointDataLayer</code>）。</li><li><a href="/src/functions/dataLoad/lineString.html">LineString</a>：添加线图层。</li><li><a href="/src/functions/dataLoad/polygon.html">Polygon</a>：添加面图层（含降雨面图层<code>addRainPolygonLayer</code>）。</li><li><a href="/src/functions/dataLoad/WMS.html">WMS</a>：加载 WMS 服务图层。</li><li><a href="/src/functions/dataLoad/WFS.html">WFS</a>：加载 WFS 服务图层。</li></ul><h2 id="要素操作" tabindex="-1">要素操作 <a class="header-anchor" href="#要素操作" aria-label="Permalink to &quot;要素操作&quot;">​</a></h2><ul><li><a href="/src/functions/featureOperation/hoverChangeStyle.html">hoverChangeStyle</a>：要素悬停时改变样式。</li><li><a href="/src/functions/featureOperation/hoverShowTips.html">hoverShowTips</a>：要素悬停时显示提示信息。</li><li><a href="/src/functions/featureOperation/pickFeaturesByName.html">pickFeaturesByName</a>：拾取范围内重叠的要素数据。</li><li><a href="/src/functions/featureOperation/pickFeaturesPopover.html">pickFeaturesPopover</a>：以弹出窗展示范围内重叠的要素数据。</li><li><a href="/src/functions/featureOperation/boxSelectionFeatures.html">boxSelectionFeatures</a>：框选地图上的要素。</li><li><a href="/src/functions/featureOperation/getWmsFeature.html">getWmsFeature</a>：获取 WMS 瓦片图层点击处的要素信息。</li><li><a href="/src/functions/featureOperation/updateWfsFilter.html">updateWfsFilter</a>：更新 WFS 图层的条件查询。</li></ul><h2 id="测量绘制" tabindex="-1">测量绘制 <a class="header-anchor" href="#测量绘制" aria-label="Permalink to &quot;测量绘制&quot;">​</a></h2><ul><li><a href="/src/functions/drawing/measureLength.html">measureLength</a>：测量距离。</li><li><a href="/src/functions/drawing/measureArea.html">measureArea</a>：测量面积。</li><li><a href="/src/functions/drawing/drawFeatures.html">drawFeatures</a>：在地图上绘制图形。</li><li><a href="/src/functions/drawing/freehandDrawing.html">freehandDrawing</a>：自由绘制（手绘）。</li></ul><h2 id="坐标转换" tabindex="-1">坐标转换 <a class="header-anchor" href="#坐标转换" aria-label="Permalink to &quot;坐标转换&quot;">​</a></h2><ul><li><a href="/src/functions/transform/projTransform.html">projTransform</a>：坐标系转换。</li><li><a href="/src/functions/transform/coordTransform.html">coordTransform</a>：常见坐标系互转（WGS-84 / GCJ-02 / BD-09 / Web墨卡托）。</li></ul><h2 id="其它常用" tabindex="-1">其它常用 <a class="header-anchor" href="#其它常用" aria-label="Permalink to &quot;其它常用&quot;">​</a></h2><ul><li><a href="/src/functions/other/exportMapToImage.html">exportMapToImage</a>：导出地图为图片。</li><li><a href="/src/functions/other/zoomToFitExtent.html">zoomToFitExtent</a>：缩放地图至适合范围。</li><li><a href="/src/functions/other/addOverlayPopup.html">addOverlayPopup</a>：通过 Overlay 在地图上添加弹窗。</li></ul>',14),o=[l];function n(s,c,h,f,u,d){return e(),r("div",null,o)}const y=a(i,[["render",n]]);export{p as __pageData,y as default};
